import{_ as a,o as t,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"MVVM","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/architecture/mvc/mvvm.md","filePath":"wiki/dev-commit/theory/architecture/mvc/mvvm.md"}'),o={name:"wiki/dev-commit/theory/architecture/mvc/mvvm.md"};function r(d,e,n,s,c,h){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="mvvm" tabindex="-1">MVVM <a class="header-anchor" href="#mvvm" aria-label="Permalink to &quot;MVVM&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Model-View-ViewModel (MVVM)</strong> - шаблон проектирования архитектуры приложения. Используется для разделения модели и её представления, что необходимо для их изменения отдельно друг от друга. Например, разработчик задаёт логику работы с данными, а дизайнер работает с пользовательским интерфейсом.</li></ul></div><h2 id="использование" tabindex="-1">Использование <a class="header-anchor" href="#использование" aria-label="Permalink to &quot;Использование&quot;">​</a></h2><ul><li>MVVM удобно использовать вместо классического MVC и ему подобных в тех случаях, когда в платформе, на которой ведётся разработка, есть «связывание данных». В шаблонах проектирования MVC/MVP изменения в пользовательском интерфейсе не влияют непосредственно на Mодель, а предварительно идут через Контроллер (англ. Controller) или Presenter. В таких технологиях как WPF и Silverlight есть концепция «связывания данных», позволяющая связывать данные с визуальными элементами в обе стороны. Следовательно, при использовании этого приёма применение модели MVC становится крайне неудобным из-за того, что привязка данных к представлению напрямую не укладывается в концепцию MVC/MVP</li></ul><h2 id="структура" tabindex="-1">Структура <a class="header-anchor" href="#структура" aria-label="Permalink to &quot;Структура&quot;">​</a></h2><h3 id="_1-модель-model" tabindex="-1">1. Модель (Model) <a class="header-anchor" href="#_1-модель-model" aria-label="Permalink to &quot;1. Модель (Model)&quot;">​</a></h3><ul><li><strong>Модель (Model)</strong> (так же, как в классической MVC) представляет собой логику работы с данными и описание фундаментальных данных, необходимых для работы приложения</li></ul><h3 id="_2-представление-view" tabindex="-1">2. Представление (View) <a class="header-anchor" href="#_2-представление-view" aria-label="Permalink to &quot;2. Представление (View)&quot;">​</a></h3><ul><li><strong>Представление (View)</strong> графический интерфейс (окна, списки, кнопки и т. п.). Выступает подписчиком на событие изменения значений свойств или команд, предоставляемых Моделью Представления. В случае, если в Модели Представления изменилось какое-либо свойство, то она оповещает всех подписчиков об этом, и Представление, в свою очередь, запрашивает обновлённое значение свойства из Модели Представления. В случае, если пользователь воздействует на какой-либо элемент интерфейса, Представление вызывает соответствующую команду, предоставленную Моделью Представления</li></ul><h3 id="_3-модель-представления-viewmodel" tabindex="-1">3. Модель Представления (ViewModel) <a class="header-anchor" href="#_3-модель-представления-viewmodel" aria-label="Permalink to &quot;3. Модель Представления (ViewModel)&quot;">​</a></h3><ul><li><strong>Модель Представления (ViewModel)</strong> с одной стороны, абстракция Представления, а с другой — обёртка данных из Модели, подлежащие связыванию. То есть, она содержит Модель, преобразованную к Представлению, а также команды, которыми может пользоваться Представление, чтобы влиять на Модель</li></ul>',12)])])}const V=a(o,[["render",r]]);export{u as __pageData,V as default};
